import React, { HTMLAttributes } from 'react';

import clsx from 'clsx';

import { uniqueId } from '@helpers/unuqueId';

import style from './styles.module.css';
const defaultAnimationDuration = 600;

export interface IPohCollapsibleProps extends Omit<HTMLAttributes<HTMLElement>, 'onToggle'> {
  activatorComponent?: ((isOpen: boolean) => React.ReactNode) | React.ReactNode;
  onToggle?: (isOpen: boolean) => void;
  open?: boolean;
  transitionDuration?: number;
}

const PohCollapsible: React.FC<IPohCollapsibleProps> = ({
  children,
  activatorComponent,
  open = false,
  onToggle,
  transitionDuration = defaultAnimationDuration,
  ...restProps
}) => {
  const [isOpen, setIsOpen] = React.useState<boolean>(open);
  const idRef = React.useRef<string>(restProps?.id || uniqueId('collapsible-'));
  const contentRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    setIsOpen(open);
  }, [open]);

  React.useEffect(() => {
    if (!contentRef.current) {
      return;
    }
    const container = contentRef.current;

    container.style.overflow = 'hidden';
    let overflowResetTimer: ReturnType<typeof setTimeout>;
    if (isOpen) {
      overflowResetTimer = setTimeout(() => {
        container.style.overflow = 'visible';
      }, transitionDuration);
    }

    return () => clearTimeout(overflowResetTimer);
  }, [contentRef, isOpen, transitionDuration]);

  const handleCollapsibleToggle = () => {
    onToggle?.(!isOpen);
    setIsOpen(!isOpen);
  };

  const activatorComp = (() => {
    const component =
      typeof activatorComponent === 'function' ? activatorComponent(isOpen) : activatorComponent;

    return React.isValidElement(component) ? component : <>{component}</>;
  })();

  const patchedActivator = activatorComp
    ? React.cloneElement(activatorComp, {
        className: clsx(activatorComp.props.className, style.collapsibleActivator),
        'aria-controls': idRef.current,
        'aria-expanded': isOpen,
        onClick: handleCollapsibleToggle,
      })
    : null;

  return (
    <div {...restProps} className={clsx('qa-collapsible', restProps.className, style.collapsible)}>
      {patchedActivator}
      <div
        ref={contentRef}
        id={idRef.current}
        role="region"
        tabIndex={-1}
        className={clsx(style.collapsibleContainer, {
          [style.collapsibleContainerClosed]: !isOpen,
        })}
        style={{ transition: `grid-template-rows ${transitionDuration}ms ease-in-out` }}
        aria-hidden={!isOpen}
      >
        <div className={style.content}>{children}</div>
      </div>
    </div>
  );
};

export default PohCollapsible;
