import React from 'react';

import ChevronDown from '@pohodnik/icons/svg/Chevrons/ChevronDown';
import ChevronRight from '@pohodnik/icons/svg/Chevrons/ChevronRight';
import clsx from 'clsx';

interface IPohCollapsibleIconProps extends React.HTMLAttributes<HTMLSpanElement> {
  open: boolean;
}

const PohCollapsibleIcon = ({ open, className }: IPohCollapsibleIconProps) => {
  return (
    <small className={clsx('d-block text-muted', className)}>
      {!open ? <ChevronRight /> : <ChevronDown />}
    </small>
  );
};

export default PohCollapsibleIcon;
